            .init(heading: "", paragraphs: ["Style Vault è un guardaroba digitale: fotografi i tuoi capi, crei outfit e li provi su di te. Qui trovi quali dati usa, dove stanno e come cancellarli."]),
            .init(heading: "Chi è il titolare", paragraphs: ["Lorenzo Faraoni, persona fisica con sede in Italia, che sviluppa Style Vault. Per qualsiasi domanda sulla privacy scrivi a lorefara97@gmail.com."]),
            .init(heading: "I tuoi dati stanno nel tuo iCloud", paragraphs: ["Capi, foto dei capi, outfit, calendario, foto del corpo, Armocromia e impostazioni si salvano sul dispositivo e nel tuo iCloud privato. Lo sviluppatore non può leggerli. L'app funziona anche senza iCloud: in quel caso restano solo sul dispositivo."]),
            .init(heading: "L'account è facoltativo", paragraphs: ["Puoi usare Style Vault senza account. Se ne crei uno, con Apple, Google o email e password, il servizio di login conserva email, nome e un identificativo; la password è conservata solo in forma cifrata. L'account serve ad accedere e a inviare segnalazioni: i tuoi capi non passano da lì.", "Chi ha usato il vecchio sito ha i suoi dati ancora su Supabase, finché non elimina l'account."]),
            .init(heading: "Cosa esce dal dispositivo", paragraphs: ["Meteo: per la previsione arrivano al Meteo di Apple le coordinate arrotondate della posizione, se scegli \"La mia posizione\", o quelle della città scelta. Apple riceve anche il testo della ricerca delle città. Le coordinate non si salvano in nessun account.", "Link dei negozi: se incolli un link, il tuo dispositivo apre direttamente quella pagina per leggerne titolo e immagine.", "Segnalazioni: se usi \"Segnala un problema o un'idea\", il testo che scrivi e alcune informazioni tecniche (versione dell'app, modello del dispositivo, versione di iOS, lingua) arrivano via email allo sviluppatore. Se scrivi via email, arriva ciò che scrivi tu.", "Negozi e servizi esterni: i collegamenti dell'Armocromia e di ChatGPT e Gemini aprono il browser o le app di quei servizi, che seguono le proprie regole."]),
            .init(heading: "Le analisi avvengono sul dispositivo", paragraphs: ["Lo scontorno dei capi, il controllo delle foto del corpo e l'Armocromia, che legge i colori del viso, usano Vision di Apple sul tuo dispositivo. Queste foto non vengono inviate a nessun servizio di intelligenza artificiale e non vengono usate per riconoscerti."]),
            .init(heading: "Se provi i capi con ChatGPT o Gemini", paragraphs: ["Il Prompt AI prepara un testo e le foto, ma l'app non invia nulla da sola. Solo se decidi tu di incollarli, quelle foto arrivano a OpenAI o a Google secondo le loro regole. Prima di continuare l'app te lo chiede. Usa solo foto tue o di chi ha dato il consenso."]),
            .init(heading: "Perché li usiamo", paragraphs: ["Per darti il servizio che chiedi (art. 6.1.b GDPR) e per rispondere alle segnalazioni e migliorare l'app (la tua richiesta e il legittimo interesse, art. 6.1.f).", "Non c'è pubblicità, non c'è tracciamento tra app o siti, non usiamo strumenti di analisi e non vendiamo dati a nessuno."]),
            .init(heading: "A chi affidiamo i dati", paragraphs: ["Apple: iCloud, accesso con Apple, Meteo di Apple, ricerca delle città.", "Supabase: login e segnalazioni, con server nell'Unione Europea (Irlanda).", "Google: solo se accedi con Google.", "Resend: invio per email delle segnalazioni, con sede negli Stati Uniti e le garanzie previste dal GDPR per i trasferimenti fuori dall'UE."]),
            .init(heading: "Per quanto tempo", paragraphs: ["I dati nel tuo iCloud restano finché li tieni tu. L'account resta finché non lo elimini: in quel momento cancelliamo account e dati rimasti sul vecchio sito, e le copie di sicurezza del fornitore si sovrascrivono entro pochi giorni. Le email delle segnalazioni restano nella casella dello sviluppatore per il tempo necessario a gestirle."]),
