            .init(heading: "Come contattarci", paragraphs: ["Dall'app: Profilo → \"Segnala un problema o un'idea\". Serve un account.", "Per email: lorefara97@gmail.com. Rispondiamo di solito entro pochi giorni."]),
            .init(heading: "I miei capi non compaiono sull'altro dispositivo", paragraphs: ["Controlla che entrambi usino lo stesso Apple ID e che iCloud sia attivo per Style Vault. La sincronizzazione può richiedere qualche minuto, e più tempo con molte foto."]),
